mapper.select:
select dmr.ID,room.PARK_ID,park.PARK_NAME,room.DORMITORY_ID,do.DORMITORY_NAME,
room.FLOOR_ID,flo.FLOOR_NAME,dmr.ROOM_ID,room.ROOM_NAME,dmr.METER_MONTH,
dmr.STATUS,dmr.STATEMENT_STATUS
from SMT_SD_METERREAD dmr
left join SMT_DORMITORY_ROOM room on dmr.ROOM_ID=room.ID
left join SMT_DORMITORY do on room.dormitory_id=do.ID
left join SMT_DORMITORY_FLOOR flo on room.floor_id=flo.ID
left join SMT_PARK park on room.park_id=park.ID


		AND room.PARK_ID=#{query.parkId}

			AND room.DORMITORY_ID=#{query.dormitoryId}

				AND room.FLOOR_ID=#{query.floorId}





		AND dmr.STATUS=#{query.status}



		AND room.ROOM_NAME like concat(concat('%',#{query.roomName}),'%')



		AND dmr.METER_MONTH=#{query.meterMonth}



		AND dmr.STATEMENT_STATUS = 1



		AND dmr.STATEMENT_STATUS=#{query.statementStatus}



		and room.PARK_ID in

			#{item}




ORDER BY flo.FLOOR_NAME,room.ROOM_NAME, dmr.STATUS

select room.id as roomId,room.PARK_ID,park.PARK_NAME,room.DORMITORY_ID, do.DORMITORY_NAME, room.FLOOR_ID,flo.FLOOR_NAME, room.ROOM_NAME from SMT_DORMITORY_ROOM room left join SMT_DORMITORY do on room.dormitory_id=do.ID left join SMT_DORMITORY_FLOOR flo on room.floor_id=flo.ID left join SMT_PARK park on room.park_id=park.ID
AND room.PARK_ID=#{query.parkId}
AND room.DORMITORY_ID=#{query.dormitoryId}
AND room.FLOOR_ID=#{query.floorId}
AND room.ROOM_NAME like concat(concat('%',#{query.roomName}),'%')
and room.PARK_ID in
#{item}
ORDER BY flo.FLOOR_NAME,room.ROOM_NAME

select room."ID" as room_id,sdm."ID" from SMT_DORMITORY_ROOM room  left join
(select ID,ROOM_ID from SMT_SD_METERREAD where METER_MONTH=#{query.meterMonth}) sdm on sdm.ROOM_ID=room.id
where room.FLOOR_ID=#{query.floorId}

select DISTINCT dmr.ID,room.SD_TEMPLATE_ID, dmr.ROOM_ID,dmr.METER_MONTH,to_char(dmr.METER_MONTH,'fmmm') as month_Num from SMT_SD_METERREAD dmr join SMT_DORMITORY_ROOM room on dmr.ROOM_ID=room.ID join SMT_SD_METERREADDETAIL sddt on dmr.ID=sddt.MR_ID WHERE room.PARK_ID in
#{item}
AND room.DORMITORY_ID=#{dormitoryId}
and room.IS_COUNT = 1 and dmr.STATUS=2 and dmr.STATEMENT_STATUS=0

select sdm.ROOM_ID,sdm.STATUS,sdm.STATEMENT_STATUS, sdmd.PRE_MONTH_NUM,sdmd.CUR_MONTH_NUM,sdmd.CATEGORY_ID,sdmd.CREATE_TIME,sdmd.REV_PRE_MONTH_NUM, sdmd.IS_REVISE,sdmd.METER_USER from SMT_SD_METERREAD sdm left join SMT_SD_METERREADDETAIL sdmd on sdm.ID=sdmd.MR_ID where sdm.ROOM_ID in
#{item}
and METER_MONTH=#{date} order by sdmd.CATEGORY_ID asc

select sdmd.ID,room.ID as ROOM_ID,nvl(room.ALIAS_NAME,room.ROOM_NAME) as ROOM_NAME,room.FLOOR_ID,room.DORMITORY_ID,room.SD_TEMPLATE_ID,room.ROOM_SEX,
sd.METER_MONTH,sd.STATEMENT_STATUS,sd.Id as mrId,sd.STATUS,
sdmd.PRE_MONTH_NUM,sdmd.REV_PRE_MONTH_NUM,sdmd.CUR_MONTH_NUM,sdmd.CATEGORY_ID,
sdmd.CUR_STD_QTY,sdmd.CUR_OVER_FEE,sdmd.TOTAL_STAY_DAYS
from SMT_DORMITORY_ROOM room
left join SMT_SD_METERREAD sd on room.ID=sd.ROOM_ID and sd.METER_MONTH=#{date}
left join SMT_SD_METERREADDETAIL sdmd on sd.ID=sdmd.MR_ID


		AND room.DORMITORY_ID=#{dormitoryId}


		AND room.DORMITORY_ID in

			#{item}



		AND room.FLOOR_ID=#{floorId}


		AND room.ID=#{roomId}


		AND room.DORMITORY_ID in

			#{item}



order by room.ID asc

select sum(c) from
(
select count(*) c from SMT_DORMITORY_STAFF WHERE STAFF_BADGE=#{badge}
UNION ALL
select count(*) c from SMT_DORMITORY_STAFF_HISTORY WHERE STAFF_BADGE=#{badge}
AND CREATE_TIME BETWEEN #{startTime} and #{endTime} and TYPE != 0
group by ROOM_ID
) t
